<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import AppButton from '@/components/ui/AppButton.vue'
import type { Product } from '@/types'
const props=defineProps<{ product?: Product|null }>(); const emit=defineEmits<{save:[payload:any];cancel:[]}>(); const saving=ref(false)
const inferCategory=(category:string,name:string)=>{const c=category.toLowerCase(),n=name.toLowerCase();if(c.includes('shoe'))return'shoes';if(c.includes('blazer')||c.includes('jacket'))return'outerwear';if(c.includes('top')||c.includes('shirt'))return'top';if(c.includes('bottom')||c.includes('trouser')||c.includes('skirt'))return'bottom';if(c.includes('dress'))return'dress';if(n.includes('bag')||n.includes('tote'))return'bag';if(n.includes('earring')||n.includes('hoop'))return'earrings';if(n.includes('necklace'))return'necklace';return'other_accessory'}

const form=reactive({name:props.product?.name||'',description:props.product?.description||'',price:props.product?.price||0,currency:props.product?.currency||'NGN',category:props.product?.category||'Tops',try_on_category:props.product?.try_on_category||'',primary_image_url:props.product?.primary_image_url||'',reference_images:(props.product?.reference_images||[]).map(x=>x.url).join('\n'),product_url:props.product?.product_url||'',sizes:(props.product?.sizes||[]).join(', '),colours:(props.product?.colours||[]).join(', '),tags:(props.product?.tags||[]).join(', '),stock_status:props.product?.stock_status||'in_stock'})
const preparedType=computed(()=>form.try_on_category||inferCategory(form.category,form.name))
const preparedSummary=computed(()=>`${form.name || 'Untitled product'}. ${form.description || 'Add a description so Mirror can preserve the important visual details.'}`)
function submit(){saving.value=true;const refs=form.reference_images.split('\n').map(x=>x.trim()).filter(Boolean);emit('save',{...form,price:Number(form.price),try_on_category:form.try_on_category||inferCategory(form.category,form.name),reference_images:refs.map((url,i)=>({url,view:i===0?'front':'detail'})),visual_description:`${form.name}. ${form.description}`,generation_constraints:{preserveColour:true,preservePattern:true,preserveLogo:true},sizes:form.sizes.split(',').map(x=>x.trim()).filter(Boolean),colours:form.colours.split(',').map(x=>x.trim()).filter(Boolean),tags:form.tags.split(',').map(x=>x.trim()).filter(Boolean)});saving.value=false}
</script>
<template><form class="grid gap-4" @submit.prevent="submit"><div class="grid gap-4 sm:grid-cols-2"><label class="text-xs font-medium">Name<input v-model="form.name" required class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><label class="text-xs font-medium">Category<select v-model="form.category" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"><option>Blazers</option><option>Tops</option><option>Bottoms</option><option>Dresses</option><option>Shoes</option><option>Accessories</option></select></label><label class="text-xs font-medium">Try-on type<select v-model="form.try_on_category" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"><option value="">Auto detect</option><option value="top">Top</option><option value="outerwear">Outerwear</option><option value="dress">Dress</option><option value="bottom">Bottom</option><option value="shoes">Shoes</option><option value="bag">Bag</option><option value="earrings">Earrings</option><option value="necklace">Necklace</option><option value="headwear">Headwear</option><option value="other_accessory">Other accessory</option></select></label><label class="text-xs font-medium">Price<input v-model.number="form.price" required min="0" type="number" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><label class="text-xs font-medium">Currency<input v-model="form.currency" required class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label></div><label class="text-xs font-medium">Description<textarea v-model="form.description" rows="3" class="mt-2 w-full rounded-xl border border-line p-3"></textarea></label><label class="text-xs font-medium">Primary product image URL<input v-model="form.primary_image_url" required type="url" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><label class="text-xs font-medium">Extra reference image URLs <span class="font-normal text-muted">(one per line; side/detail views help shoes and accessories)</span><textarea v-model="form.reference_images" rows="3" class="mt-2 w-full rounded-xl border border-line p-3" placeholder="https://.../side.jpg\nhttps://.../detail.jpg"></textarea></label><label class="text-xs font-medium">Merchant product URL<input v-model="form.product_url" required type="url" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><div class="grid gap-4 sm:grid-cols-3"><label class="text-xs font-medium">Sizes<input v-model="form.sizes" placeholder="S, M, L" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><label class="text-xs font-medium">Colours<input v-model="form.colours" placeholder="Navy, Black" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label><label class="text-xs font-medium">Tags<input v-model="form.tags" placeholder="workwear, modest" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"/></label></div><label class="text-xs font-medium">Stock<select v-model="form.stock_status" class="mt-2 min-h-11 w-full rounded-xl border border-line px-3"><option value="in_stock">In stock</option><option value="low_stock">Low stock</option><option value="out_of_stock">Out of stock</option></select></label><div class="rounded-[1.1rem] border border-line bg-paper p-4"><div class="flex items-center justify-between"><div><p class="text-[10px] font-semibold uppercase tracking-[.18em] text-muted">Mirror preparation</p><p class="mt-1 text-xs font-semibold">{{ preparedType }}</p></div><span class="rounded-full bg-white px-2.5 py-1 text-[10px] font-semibold">Auto-prepared</span></div><p class="mt-3 text-xs leading-5 text-muted">{{ preparedSummary }}</p><p class="mt-2 text-[10px] leading-4 text-muted">Colour, pattern, logo and distinctive product details are marked for preservation. Side/detail reference images are especially useful for shoes, bags and jewellery.</p></div><div class="flex justify-end gap-2"><AppButton variant="ghost" @click="$emit('cancel')">Cancel</AppButton><AppButton type="submit" :disabled="saving">Save product</AppButton></div></form></template>
